using Acme.EntityFrameworkCore.Tenancy;
using Acme.EntityFrameworkCore.Tenancy.Metadata;
using Consumer;
using Microsoft.EntityFrameworkCore;

// Checks the runtime behavior of the model the application uses. With COMPILED_MODEL the model
// generated by "dotnet ef dbcontext optimize" is loaded through UseModel; that context has no
// query filter, because EF Core 10 does not compile models with query filters.
var failures = new List<string>();
void Check(bool condition, string what)
{
    Console.WriteLine($"{(condition ? "ok  " : "FAIL")} {what}");
    if (!condition)
        failures.Add(what);
}

#if COMPILED_MODEL
using DbContext db = new CompiledPgContext(Options.CompiledPg()
    .UseModel(Consumer.CompiledModels.CompiledPgContextModel.Instance).Options);
const bool queryFilter = false;
#else
using DbContext db = new PgContext(Options.Pg().Options);
const bool queryFilter = true;
#endif

var order = db.Model.FindEntityType(typeof(Order))!;
var tenantId = order.FindProperty(nameof(Order.TenantId))!;
Console.WriteLine($"     model type {db.Model.GetType().FullName}");
#if COMPILED_MODEL
Check(db.Model.GetType().FullName!.StartsWith("Consumer.CompiledModels", StringComparison.Ordinal),
    "the compiled model is used");
#endif
Check(tenantId.GetRelationalTypeMapping().StoreType == "uuid", "TenantId maps to uuid");
Check(order.GetTenantPropertyName() == "TenantId", "runtime annotation names the tenant property");

var orders = db.Set<Order>();
var sql = orders.Where(o => o.TenantId == EF.Functions.CurrentTenant()).ToQueryString();
Check(sql.Contains("current_setting('app.tenant_id', TRUE)", StringComparison.Ordinal),
    "CurrentTenant() is translated");
Check(orders.ToQueryString().Contains("current_setting", StringComparison.Ordinal) == queryFilter,
    queryFilter ? "named query filter is applied" : "no query filter (RLS alone)");

return failures.Count == 0 ? 0 : 1;
